    /// <summary>Gets all available icon names.</summary>
    public static IEnumerable<string> Names => s_icons.Keys;

    /// <summary>Gets the inner SVG markup of an icon.</summary>
    /// <param name="name">The icon name.</param>
    /// <returns>The SVG child elements.</returns>
    public static string Get(string? name) => name is not null && s_icons.TryGetValue(name, out var markup) ? markup : Fallback;
